window.PAPERS={"math": {"label": "数学", "name": "第一单元 B卷 · 分数除法", "pages": "3—4", "description": "从看图列式到应用题，先找准整体和部分，再说清数量关系。", "questions": [{"id": "m-f1", "title": "填空1｜看图列除法", "type": "填空", "prompt": "看图，填写：<p>（　）÷（　）＝（　）×（　）＝（　）</p>", "answer": "8/9 ÷ 4 ＝ 8/9 × 1/4 ＝ 2/9", "steps": ["整个长条平均分成9小格，阴影占8格，所以阴影表示8/9。", "把阴影平均分成4份，每份就是8/9÷4。", "除以4等于乘1/4，得到2/9。"], "hints": ["先数整个长条分成几格，再数阴影几格。", "阴影被分成几份？每份求什么？"], "pitfall": "单位“1”是整个长条，不是阴影部分。", "sourcePage": 3, "diagram": "<svg viewBox=\"0 0 760 210\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:24px;font-family:sans-serif\" aria-label=\"题目示意图\"><rect x=\"70\" y=\"45\" width=\"64\" height=\"68\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"134\" y=\"45\" width=\"64\" height=\"68\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"198\" y=\"45\" width=\"64\" height=\"68\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"262\" y=\"45\" width=\"64\" height=\"68\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"326\" y=\"45\" width=\"64\" height=\"68\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"390\" y=\"45\" width=\"64\" height=\"68\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"454\" y=\"45\" width=\"64\" height=\"68\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"518\" y=\"45\" width=\"64\" height=\"68\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"582\" y=\"45\" width=\"64\" height=\"68\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><text x=\"70\" y=\"155\">整个长条表示 1；阴影平均分成4份。</text></svg>"}, {"id": "m-f2", "title": "填空2｜已知部分求整体", "type": "填空", "prompt": "<p>（　）km的3/8是6 km；</p><p>6 km的3/8是（　）km；</p><p>4/5 kg的（　）是3/10 kg。</p>", "answer": "16；9/4；3/8", "steps": ["第1空：整体×3/8＝6，整体＝6÷3/8＝16（km）。", "第2空：已知整体6，求它的3/8，用6×3/8＝9/4（km）。", "第3空：3/10是4/5的几分之几，用3/10÷4/5＝3/8。"], "hints": ["每小问分别说出整体、部分和对应分率。", "求整体用“部分÷对应分率”；求分率用“部分÷整体”。"], "pitfall": "同样出现“的3/8”，要看问的是整体还是部分。", "sourcePage": 3}, {"id": "m-f3", "title": "填空3｜除数大小与商", "type": "填空", "prompt": "分别将2、3/2和1/2填入对应的括号里：<p>5/12 ÷（　）＜5/12 ÷（　）＜5/12 ÷（　）</p>", "answer": "依次填：2，3/2，1/2", "steps": ["三个算式的被除数相同，都是正数5/12。", "正的被除数不变，除数越大，商越小。", "除数从大到小是2、3/2、1/2，所以按这个顺序填。"], "hints": ["先比较2、1.5、0.5的大小。", "要让商从小到大，除数应该怎样排列？"], "pitfall": "别把除数从小到大的顺序直接填进去。", "sourcePage": 3}, {"id": "m-f4", "title": "填空4｜四种分数除法算法", "type": "填空", "prompt": "天天步行去体育公园，3/5小时行了9/10 km。平均每小时步行多少千米？有四种算法：<p>① 9/10÷3/5＝9/10×5/3＝3/2</p><p>② 9/10÷3/5＝9/10÷6/10＝9÷6＝3/2</p><p>③ 9/10÷3/5＝9/10×1/3×5＝3/2</p><p>④ 9/10÷3/5＝9/10÷9/15＝1/10÷1/15＝3/2</p><p>（1）算法③中，9/10×1/3表示（　）小时步行的路程。</p><p>（2）借助统一“分数单位”来计算的是算法（　）；借助统一“分数单位的个数”来计算的是算法（　）。</p>", "answer": "（1）1/5；（2）②，④", "steps": ["3/5小时分成3份，每份是1/5小时，所以9/10×1/3表示1/5小时的路程。", "②把3/5化成6/10，两个分数的单位统一成1/10，比9个和6个同样单位。", "④把两个分数写成9个1/10和9个1/15，分数单位的个数都为9，再比较每个单位。"], "hints": ["算法③先除以3，时间也要同时分成3份。", "②和④，哪一种统一了分母，哪一种统一了分子？"], "pitfall": "③不是先求1小时路程；先求的是1/5小时路程。", "sourcePage": 3}, {"id": "m-f5", "title": "填空5｜等量关系求b", "type": "填空", "prompt": "已知3/4 a＝4/5 b，如果a＝64，那么b＝（　）。", "answer": "60", "steps": ["先算相等的量：3/4×64＝48。", "所以4/5 b＝48，b＝48÷4/5＝60。", "检验：60×4/5＝48，与64×3/4相同。"], "hints": ["先把a＝64代入左边。", "b的4/5是48，求b要用什么运算？"], "pitfall": "不能把48直接乘4/5。", "sourcePage": 3}, {"id": "m-f6", "title": "填空6｜修路的工作效率", "type": "填空", "prompt": "某工程队修一段公路，修了8天还剩3/5没修，平均每天修这条公路的（　）；照这个工效，剩下的公路还需（　）天才能修完。", "answer": "1/20；12", "steps": ["整条公路看作1，已修1－3/5＝2/5。", "8天修2/5，平均每天修2/5÷8＝1/20。", "剩下3/5，所需天数＝3/5÷1/20＝12（天）。"], "hints": ["8天对应的是已修部分还是剩下部分？", "每天修的分率＝已修分率÷天数。"], "pitfall": "题目说“还剩3/5”，不能用3/5÷8算已完成的效率。", "sourcePage": 3, "diagram": "<svg viewBox=\"0 0 760 230\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:23px;font-family:sans-serif\" aria-label=\"数量关系线段图\"><text x=\"70\" y=\"30\">整条公路看作 1</text><rect x=\"70.0\" y=\"65\" width=\"120.0\" height=\"48\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"190.0\" y=\"65\" width=\"120.0\" height=\"48\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"310.0\" y=\"65\" width=\"120.0\" height=\"48\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"430.0\" y=\"65\" width=\"120.0\" height=\"48\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"550.0\" y=\"65\" width=\"120.0\" height=\"48\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><text x=\"70\" y=\"160\">前面已修（8天）　｜　后面剩下3/5未修</text></svg>"}, {"id": "m-f7", "title": "填空7｜从第61页开始", "type": "填空", "prompt": "华华看一本书，前4天一共看了全书的2/7，第5天她从第61页开始看起。这本书一共有（　）页。", "answer": "210", "steps": ["第5天从61页开始，说明前4天看完了第1—60页，共60页。", "60页对应全书的2/7。", "全书页数＝60÷2/7＝210（页）。"], "hints": ["从第61页开始之前，已经看完多少页？", "60页相当于全书的几分之几？"], "pitfall": "61是下一页的页码，不是已看页数。", "sourcePage": 3, "diagram": "<svg viewBox=\"0 0 760 230\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:23px;font-family:sans-serif\" aria-label=\"数量关系线段图\"><text x=\"70\" y=\"30\">全书看作 1（平均分成7份）</text><rect x=\"70.0\" y=\"65\" width=\"85.71428571428571\" height=\"48\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"155.71428571428572\" y=\"65\" width=\"85.71428571428571\" height=\"48\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"241.42857142857142\" y=\"65\" width=\"85.71428571428571\" height=\"48\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"327.14285714285717\" y=\"65\" width=\"85.71428571428571\" height=\"48\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"412.85714285714283\" y=\"65\" width=\"85.71428571428571\" height=\"48\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"498.57142857142856\" y=\"65\" width=\"85.71428571428571\" height=\"48\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"584.2857142857143\" y=\"65\" width=\"85.71428571428571\" height=\"48\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><text x=\"70\" y=\"160\">前4天已看2份；第5天从第61页开始</text></svg>"}, {"id": "m-f8", "title": "填空8｜为什么除以分数等于乘倒数", "type": "填空", "prompt": "验证“除以一个不等于0的数等于乘这个数的倒数”：<p>3/4÷2/3＝(3/4×3/2)÷(2/3×3/2)＝(3/4×3/2)÷1＝3/4×3/2。</p><p>（1）被除数和除数可以同时乘3/2是利用了（　）。</p><p>（2）请运用上面的方法验证a÷b＝a×1/b（b≠0）。</p>", "answer": "（1）商不变性质；（2）a÷b＝(a×1/b)÷(b×1/b)＝(a×1/b)÷1＝a×1/b。", "steps": ["被除数和除数同时乘同一个不为0的数，商不变。", "为了让除数b变成1，给它乘倒数1/b。", "被除数也要同时乘1/b，最后除以1，结果不变。"], "hints": ["为什么要乘3/2？它和2/3相乘是多少？", "要把除数b变成1，应给两个数同时乘什么？"], "pitfall": "必须两个数同时乘；乘数不为0，且b≠0。", "sourcePage": 3}, {"id": "m-f9", "title": "填空9｜公交车有多少座位", "type": "填空", "prompt": "一辆公交车从起点站出发，开始时每人一个座位，正好坐满。下一站下车1/3后，又上来8人，这时座位不够，有2人只好站着。公交车一共有（　）个座位。", "answer": "18", "steps": ["原来正好坐满，下车几人就空出几个座位。", "上来8人，有2人站着，说明空位只有8－2＝6（个）。", "6个座位对应原座位总数的1/3，总座位数＝6÷1/3＝18（个）。"], "hints": ["上来8人，有2人站着，真正坐下的有几人？", "下车人数对应总座位数的几分之几？"], "pitfall": "不能把上车的8人全部当作原来下车的人数。", "sourcePage": 3, "diagram": "<svg viewBox=\"0 0 760 230\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:23px;font-family:sans-serif\" aria-label=\"数量关系线段图\"><text x=\"70\" y=\"30\">原来正好坐满：总座位数看作1</text><rect x=\"70.0\" y=\"65\" width=\"200.0\" height=\"48\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"270.0\" y=\"65\" width=\"200.0\" height=\"48\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"470.0\" y=\"65\" width=\"200.0\" height=\"48\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"2\"/><text x=\"70\" y=\"160\">下一站下车1/3，腾出右边1份座位</text></svg>"}, {"id": "m-f10", "title": "填空10｜长方形面积与高的比", "type": "填空", "prompt": "如图，涂色长方形的面积是20 cm²，线段BE的长度是AE长度的2/3。整个大长方形的面积是（　）cm²。", "answer": "50", "steps": ["上下两个长方形宽相同，面积的比等于高的比。", "BE是AE的2/3，所以阴影面积20也是上面空白面积的2/3。", "空白面积＝20÷2/3＝30（cm²），总面积＝20＋30＝50（cm²）。"], "hints": ["两个小长方形的哪一条边相同？", "BE比较的是AE，不是AB。"], "pitfall": "2/3的单位“1”是上面空白部分对应的高，不是整个长方形的高。", "sourcePage": 3, "diagram": "<svg viewBox=\"0 0 760 210\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:24px;font-family:sans-serif\" aria-label=\"题目示意图\"><rect x=\"250\" y=\"20\" width=\"220\" height=\"150\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"3\"/><rect x=\"250\" y=\"110\" width=\"220\" height=\"60\" fill=\"#c8dbd1\" stroke=\"#365d50\" stroke-width=\"3\"/><text x=\"210\" y=\"30\">A</text><text x=\"210\" y=\"115\">E</text><text x=\"210\" y=\"175\">B</text><text x=\"480\" y=\"30\">D</text><text x=\"480\" y=\"115\">F</text><text x=\"480\" y=\"175\">C</text><text x=\"280\" y=\"150\">20 cm²</text></svg>"}, {"id": "m-c1", "title": "选择1｜哪幅图不能表示原式", "type": "选择", "prompt": "下列各图中，不能用3/5÷3表示的是（　）。<p><img src=\"assets/math/choice-1.webp\" alt=\"原卷A、B、C、D四幅图\" style=\"width:100%;max-width:900px\"></p>", "answer": "B", "steps": ["先说出算式的图意：把整个单位“1”的3/5平均分成3份，求其中1份。", "A、C、D都在表示先取整体的3/5，再把这部分平均分成3份。", "B图先把整体平均分成3份，再取其中一份的3/5，直接表示1/3×3/5。虽然数值相等，图示过程与题中除法的直接意义不同。"], "hints": ["先别看结果，先说“3/5÷3”在做什么。", "每幅图里先取出的整体部分是谁？"], "pitfall": "本题考图示过程，不能只因为几个结果都是1/5就说图意完全一样。", "sourcePage": 3}, {"id": "m-c2", "title": "选择2｜商在哪个范围", "type": "选择", "prompt": "下列算式的结果在1/5～7/10之间的是（　）。<p>A. 2/5÷3/2　 B. 1÷7/10</p><p>C. 7/10÷2/5　 D. 1/5÷2</p>", "answer": "A", "steps": ["A＝2/5×2/3＝4/15，介于1/5＝3/15和7/10之间。", "B＝10/7＞1；C＝7/4＞1；都大于7/10。", "D＝1/10，小于1/5。"], "hints": ["先看哪些结果大于1，可直接排除。", "A算出4/15后，与1/5通分比较。"], "pitfall": "“在……之间”要求同时大于下限、小于上限。", "sourcePage": 3}, {"id": "m-c3", "title": "选择3｜数轴上的乘除大小", "type": "选择", "prompt": "如图，a、b、c的大小在数轴上表示如下，那么下列各式中，得数最大的是（　）。<p>A. c×a　 B. c÷a　 C. c×b　 D. c÷b</p>", "answer": "B", "steps": ["由数轴可知0＜a＜b＜1＜c。", "c乘小于1的正数会变小，所以c×a、c×b都小于c。", "c除以小于1的正数会变大；又a＜b，同一个正数c除以更小的a得到更大的商。"], "hints": ["先按数轴写出a、b、1、c的大小。", "c÷a与c÷b被除数相同，哪个除数更小？"], "pitfall": "不要把“乘法一定变大、除法一定变小”当成规律。", "sourcePage": 3, "diagram": "<svg viewBox=\"0 0 760 210\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:24px;font-family:sans-serif\" aria-label=\"题目示意图\"><line x1=\"70\" y1=\"100\" x2=\"700\" y2=\"100\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M700 100 l-14 -8 v16 z\" fill=\"#365d50\"/><line x1=\"90\" y1=\"90\" x2=\"90\" y2=\"110\" stroke=\"#365d50\"/><text x=\"82\" y=\"145\">0</text><line x1=\"270\" y1=\"90\" x2=\"270\" y2=\"110\" stroke=\"#365d50\"/><text x=\"262\" y=\"145\">1</text><line x1=\"450\" y1=\"90\" x2=\"450\" y2=\"110\" stroke=\"#365d50\"/><text x=\"442\" y=\"145\">2</text><line x1=\"630\" y1=\"90\" x2=\"630\" y2=\"110\" stroke=\"#365d50\"/><text x=\"622\" y=\"145\">3</text><circle cx=\"180\" cy=\"100\" r=\"5\" fill=\"#365d50\"/><text x=\"173\" y=\"75\">a</text><circle cx=\"235\" cy=\"100\" r=\"5\" fill=\"#365d50\"/><text x=\"228\" y=\"75\">b</text><circle cx=\"395\" cy=\"100\" r=\"5\" fill=\"#365d50\"/><text x=\"388\" y=\"75\">c</text></svg>"}, {"id": "m-c4", "title": "选择4｜标记重捕估算鱼数", "type": "选择", "prompt": "生物学家采用“标记重捕法”估计池塘里鲫鱼的条数。第一次捕获30条鲫鱼，做上标记放回池塘；第二次捕获18条，其中3条有标记，占这次捕获数的1/6。根据该方法，推断出第一次捕获的鲫鱼大约占池塘鲫鱼总数的1/6，所以池塘中大约有（　）条鲫鱼。<p>A.18　B.108　C.180　D.540</p>", "answer": "C，约180条", "steps": ["题目采用的估计前提：池塘全部鱼中，做标记的鱼也约占1/6。", "第一次做标记的鱼是30条，30对应总数的1/6。", "估计总数＝30÷1/6＝180（条）。"], "hints": ["这里用哪一批鱼的条数对应全池的1/6？", "已知总数的1/6是30，求总数。"], "pitfall": "第二次18条是抽样数，不是全池的1/6；估算要按题目给出的推断。", "sourcePage": 3}, {"id": "m-c5", "title": "选择5｜相同的商，不同的被除数", "type": "选择", "prompt": "若a、b、c都大于0，且a÷7/6＝b÷2/3＝c÷2，则下列排序正确的是（　）。<p>A. a＞b＞c　B. c＞b＞a</p><p>C. a＞c＞b　D. c＞a＞b</p>", "answer": "D", "steps": ["把三个相同的商设为k，k＞0。", "则a＝7/6 k，b＝2/3 k，c＝2k。", "因为2＞7/6＞2/3，所以c＞a＞b。"], "hints": ["假设三个商都等于1，各被除数会是多少？", "被除数＝商×除数。"], "pitfall": "这里是商相同，不是被除数相同，别套用“除数越大商越小”。", "sourcePage": 3}, {"id": "m-c6", "title": "选择6｜三数量的关系", "type": "选择", "prompt": "已知甲数是乙数的1/3，甲数是丙数的2/5，乙数是36，则丙数是（　）。<p>A.4.8　B.43.2　C.30　D.54</p>", "answer": "C，30", "steps": ["先由乙数求甲数：36×1/3＝12。", "甲数是丙数的2/5，即丙数×2/5＝12。", "丙数＝12÷2/5＝30。"], "hints": ["第一个关系里，谁是单位“1”？", "第二个关系里，已知部分12，要求哪个整体？"], "pitfall": "两个“是……的”对应的单位“1”不同，不能一路直接乘。", "sourcePage": 3}, {"id": "m-c7", "title": "选择7｜谁原来的零用钱更多", "type": "选择", "prompt": "母亲节到了，典典和华华分别花40元为各自的妈妈买了一束鲜花。典典花了自己零用钱的1/5，华华花了自己零用钱的1/4，原来谁的零用钱更多？下面三位同学不同的比较方法，思路正确的有（　）。<p><img src=\"assets/math/choice-7.webp\" alt=\"①两条线段图 ②因1/4大于1/5所以华华钱更多 ③用40分别除以对应分率\" style=\"width:100%;max-width:900px\"></p><p>A.①　B.②　C.③　D.①③</p>", "answer": "D，①③", "steps": ["①把同样的40元看作一份，典典总钱数有5份，华华有4份，典典更多。", "②只比1/4和1/5，忽略两人的整体不同；同样花40元，所占比例越小，原来总钱数反而越多。", "③典典：40÷1/5＝200（元）；华华：40÷1/4＝160（元）。200＞160，所以③也对。"], "hints": ["两人花掉的40元是相同的量。", "5份40元多，还是4份40元多？"], "pitfall": "不能在单位“1”不同的情况下，只比较分率就比较总量。", "sourcePage": 3}, {"id": "m-k1", "title": "计算1-1｜8÷7/4", "type": "计算", "prompt": "8÷7/4＝", "answer": "32/7", "steps": ["先把除法改成乘法，只把除数换成倒数。", "8×4/7＝32/7。", "检查能否约分，结果要是最简分数。"], "hints": ["圈出除数，先写它的倒数。", "能先交叉约分再乘吗？"], "pitfall": "不要把被除数也取倒数。", "sourcePage": 3}, {"id": "m-k2", "title": "计算1-2｜3/8÷9/16", "type": "计算", "prompt": "3/8÷9/16＝", "answer": "2/3", "steps": ["先把除法改成乘法，只把除数换成倒数。", "3/8×16/9＝2/3。", "检查能否约分，结果要是最简分数。"], "hints": ["圈出除数，先写它的倒数。", "能先交叉约分再乘吗？"], "pitfall": "不要把被除数也取倒数。", "sourcePage": 3}, {"id": "m-k3", "title": "计算1-3｜4/5÷5/4", "type": "计算", "prompt": "4/5÷5/4＝", "answer": "16/25", "steps": ["先把除法改成乘法，只把除数换成倒数。", "4/5×4/5＝16/25。", "检查能否约分，结果要是最简分数。"], "hints": ["圈出除数，先写它的倒数。", "能先交叉约分再乘吗？"], "pitfall": "不要把被除数也取倒数。", "sourcePage": 3}, {"id": "m-k4", "title": "计算1-4｜14÷7/4", "type": "计算", "prompt": "14÷7/4＝", "answer": "8", "steps": ["先把除法改成乘法，只把除数换成倒数。", "14×4/7＝8。", "检查能否约分，结果要是最简分数。"], "hints": ["圈出除数，先写它的倒数。", "能先交叉约分再乘吗？"], "pitfall": "不要把被除数也取倒数。", "sourcePage": 3}, {"id": "m-k5", "title": "计算1-5｜35/24÷7/12", "type": "计算", "prompt": "35/24÷7/12＝", "answer": "5/2", "steps": ["先把除法改成乘法，只把除数换成倒数。", "35/24×12/7＝5/2。", "检查能否约分，结果要是最简分数。"], "hints": ["圈出除数，先写它的倒数。", "能先交叉约分再乘吗？"], "pitfall": "不要把被除数也取倒数。", "sourcePage": 3}, {"id": "m-k6", "title": "计算1-6｜8/34÷4/51", "type": "计算", "prompt": "8/34÷4/51＝", "answer": "3", "steps": ["先把除法改成乘法，只把除数换成倒数。", "8/34×51/4＝3。", "检查能否约分，结果要是最简分数。"], "hints": ["圈出除数，先写它的倒数。", "能先交叉约分再乘吗？"], "pitfall": "不要把被除数也取倒数。", "sourcePage": 3}, {"id": "m-k7", "title": "计算1-7｜8/3÷5/11", "type": "计算", "prompt": "8/3÷5/11＝", "answer": "88/15", "steps": ["先把除法改成乘法，只把除数换成倒数。", "8/3×11/5＝88/15。", "检查能否约分，结果要是最简分数。"], "hints": ["圈出除数，先写它的倒数。", "能先交叉约分再乘吗？"], "pitfall": "不要把被除数也取倒数。", "sourcePage": 3}, {"id": "m-k8", "title": "计算1-8｜4/9÷6", "type": "计算", "prompt": "4/9÷6＝", "answer": "2/27", "steps": ["先把除法改成乘法，只把除数换成倒数。", "4/9×1/6＝2/27。", "检查能否约分，结果要是最简分数。"], "hints": ["圈出除数，先写它的倒数。", "能先交叉约分再乘吗？"], "pitfall": "不要把被除数也取倒数。", "sourcePage": 3}, {"id": "m-rule", "title": "计算2｜整数、小数、分数除法的一致性", "type": "计算", "prompt": "典典根据整数、小数、分数除法运算是否具有一致性，过程如下：<p>800÷400＝(800÷100)÷(400÷100)＝8÷4＝2</p><p>0.32÷0.08＝(0.32×100)÷(0.08×100)＝32÷8＝4</p><p>3/8÷2/5＝(3/8×40)÷(2/5×40)＝15÷16＝15/16</p><p>以上呈现的除法运算的一致性是它们都运用了（　）的性质进行计算。</p>", "answer": "商不变性质", "steps": ["观察三个例子，被除数和除数做了同样的变化。", "第1组同时除以100，第2组同时乘100，第3组同时乘40。", "在除数不为0时，被除数和除数同时乘或除以同一个不为0的数，商不变。"], "hints": ["两个数有没有同时改变？改变的倍数是否相同？", "这条性质的名称里有“商”。"], "pitfall": "只改变一个数，商一般会改变。", "sourcePage": 3}, {"id": "m-rule-a", "title": "计算2-①｜用商不变性质算", "type": "计算", "prompt": "请用商不变性质计算：<p>3/4÷2/3</p>", "answer": "9/8", "steps": ["4和3的公倍数可取12。", "3/4÷2/3＝(3/4×12)÷(2/3×12)＝9÷8＝9/8。", "同时乘12，把两个分数都化为整数，商保持不变。"], "hints": ["给两个分数同时乘几，能让它们都变成整数？", "4和3的最小公倍数是多少？"], "pitfall": "本题要求展示商不变性质的过程，不能只报乘倒数的结果。", "sourcePage": 3}, {"id": "m-rule-b", "title": "计算2-②｜用商不变性质算", "type": "计算", "prompt": "请用商不变性质计算：<p>4/7÷3/5</p>", "answer": "20/21", "steps": ["7和5的公倍数可取35。", "4/7÷3/5＝(4/7×35)÷(3/5×35)＝20÷21＝20/21。", "同一个算式里的被除数和除数必须乘同一个数。"], "hints": ["35能同时消去哪个分母？", "分别算出4/7×35和3/5×35。"], "pitfall": "不能给第一个分数乘7、第二个乘5，那样两个变化倍数不同。", "sourcePage": 3}, {"id": "m-o1", "title": "操作题｜用图表示2/5平方米", "type": "操作", "prompt": "同同要为一个2 m²的宣传板画一幅插画，插画的面积有2/5 m²。如果用下面的长方形表示2 m²，请在长方形中画格、涂色（或用不同线条）表示插画的面积。", "answer": "把整个长方形平均分成5份，涂其中1份。", "steps": ["先问：插画面积占整块板的几分之几？", "2/5÷2＝1/5，所以插画占整块板的1/5。", "将表示2 m²的整块长方形平均分为5份，每份是2/5 m²，涂1份。"], "hints": ["整块图表示2 m²，不是1 m²。", "2/5 m²占2 m²的几分之几？"], "pitfall": "不要把整个图的2/5涂色，那表示4/5 m²。", "sourcePage": 4, "diagram": "<svg viewBox=\"0 0 760 210\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:24px;font-family:sans-serif\" aria-label=\"题目示意图\"><rect x=\"180\" y=\"25\" width=\"400\" height=\"120\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"3\"/><text x=\"210\" y=\"190\">整个长方形表示 2 m²</text></svg>"}, {"id": "m-p1", "title": "解决问题1｜彩旗之间的距离", "type": "应用", "prompt": "把10面彩旗平均插在长4/5 km的水泥路一侧（路两端都插），相邻两面彩旗之间的距离相同，那么相邻两面彩旗之间的距离是多少千米？", "answer": "4/45 km", "steps": ["两端都插，10面彩旗之间共有10－1＝9个间隔。", "全长4/5 km平均分成9段。", "相邻距离＝4/5÷9＝4/45（km）。"], "hints": ["先画3面旗看看，中间有几个间隔。", "应该把全长平均分成10份，还是9份？"], "pitfall": "旗数和间隔数不一样；两端都插时，间隔数比旗数少1。", "sourcePage": 4, "diagram": "<svg viewBox=\"0 0 760 230\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:23px;font-family:sans-serif\" aria-label=\"数量关系线段图\"><line x1=\"65\" y1=\"130\" x2=\"695\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><line x1=\"65\" y1=\"65\" x2=\"65\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M65 65 l25 12 -25 12 z\" fill=\"#ca8c48\"/><line x1=\"135\" y1=\"65\" x2=\"135\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M135 65 l25 12 -25 12 z\" fill=\"#ca8c48\"/><line x1=\"205\" y1=\"65\" x2=\"205\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M205 65 l25 12 -25 12 z\" fill=\"#ca8c48\"/><line x1=\"275\" y1=\"65\" x2=\"275\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M275 65 l25 12 -25 12 z\" fill=\"#ca8c48\"/><line x1=\"345\" y1=\"65\" x2=\"345\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M345 65 l25 12 -25 12 z\" fill=\"#ca8c48\"/><line x1=\"415\" y1=\"65\" x2=\"415\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M415 65 l25 12 -25 12 z\" fill=\"#ca8c48\"/><line x1=\"485\" y1=\"65\" x2=\"485\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M485 65 l25 12 -25 12 z\" fill=\"#ca8c48\"/><line x1=\"555\" y1=\"65\" x2=\"555\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M555 65 l25 12 -25 12 z\" fill=\"#ca8c48\"/><line x1=\"625\" y1=\"65\" x2=\"625\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M625 65 l25 12 -25 12 z\" fill=\"#ca8c48\"/><line x1=\"695\" y1=\"65\" x2=\"695\" y2=\"130\" stroke=\"#365d50\" stroke-width=\"3\"/><path d=\"M695 65 l25 12 -25 12 z\" fill=\"#ca8c48\"/><text x=\"150\" y=\"185\">路两端都插；这条路全长4/5 km</text></svg>"}, {"id": "m-p2", "title": "解决问题2｜退票手续费", "type": "应用", "prompt": "按照铁路部门的规定，高铁票退票需要扣除手续费，部分规定如下：<table><tr><th>距离开车时间</th><th>退票手续费</th></tr><tr><td>8天以上（含8天）</td><td>免费</td></tr><tr><td>48小时及以上，8天以内</td><td>票面价的1/20</td></tr><tr><td>24小时及以上，48小时以内</td><td>票面价的1/10</td></tr><tr><td>24小时以内</td><td>票面价的1/5</td></tr></table><p>荣老师准备去外地出差，在铁路12306 APP上买了一张7月3日12:35发车的高铁票，但是他在7月2日12:30接到取消出差的通知，过了10分钟才取消订票，结果被扣了25元。荣老师购买的高铁票是多少元？</p>", "answer": "125元", "steps": ["取消订票时间是7月2日12:30＋10分钟＝12:40。", "距离7月3日12:35发车还有23小时55分钟，属于24小时以内。", "手续费是票价的1/5，票价＝25÷1/5＝125（元）。"], "hints": ["先算实际退票时间，不是接到通知的时间。", "实际退票时距离开车满24小时吗？"], "pitfall": "不要按12:30判断；晚了10分钟，收费档位就变了。", "sourcePage": 4}, {"id": "m-p3", "title": "解决问题3｜根据线段图编题", "type": "应用", "prompt": "根据线段图，请把它编成一道完整的数学问题再解答。", "answer": "示例：儿童体内水分约占体重的4/5，典典体内有水分28 kg。典典的体重是多少千克？28÷4/5＝35（kg）。", "steps": ["先确定整条线段表示典典的体重，平均分成5份。", "其中4份表示体内水分，共28 kg。", "可以先求1份：28÷4＝7（kg），再求5份：7×5＝35（kg）；合并就是28÷4/5。"], "hints": ["图上的28 kg对应几份？要求的是几份？", "编题要有已知分率、已知数量和明确的问题。"], "pitfall": "28 kg是水分质量，不是总的体重。", "sourcePage": 4, "diagram": "<svg viewBox=\"0 0 760 235\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:24px;font-family:sans-serif\" aria-label=\"题目示意图\"><text x=\"70\" y=\"35\">儿童体内水分约占体重的4/5</text><rect x=\"70\" y=\"70\" width=\"600\" height=\"54\" fill=\"white\" stroke=\"#365d50\" stroke-width=\"2\"/><rect x=\"70\" y=\"70\" width=\"120\" height=\"54\" fill=\"#c8dbd1\" stroke=\"#365d50\"/><rect x=\"190\" y=\"70\" width=\"120\" height=\"54\" fill=\"#c8dbd1\" stroke=\"#365d50\"/><rect x=\"310\" y=\"70\" width=\"120\" height=\"54\" fill=\"#c8dbd1\" stroke=\"#365d50\"/><rect x=\"430\" y=\"70\" width=\"120\" height=\"54\" fill=\"#c8dbd1\" stroke=\"#365d50\"/><rect x=\"550\" y=\"70\" width=\"120\" height=\"54\" fill=\"white\" stroke=\"#365d50\"/><text x=\"170\" y=\"158\">体内水分：28 kg</text><text x=\"240\" y=\"200\">体重：？kg</text></svg>"}, {"id": "m-p4", "title": "解决问题4｜环湖骑行剩下多少", "type": "应用", "prompt": "聪聪去参加环湖骑行大赛，如图表所示。聪聪最后10分钟骑行了全程的几分之几？如果从冲刺点到终点有2 km，那么全程有多少千米？<table><tr><th>骑行时长</th><th>路程</th></tr><tr><td>15分钟</td><td>从起点到补给站，相当于全程的2/7</td></tr><tr><td>20分钟</td><td>从补给站到冲刺点，相当于全程的2/3</td></tr><tr><td>10分钟</td><td>从冲刺点到终点</td></tr></table>", "answer": "最后10分钟骑行全程的1/21；全程42 km。", "steps": ["把全程看作1，前两段分别占全程的2/7、2/3。", "最后一段占1－2/7－2/3＝21/21－6/21－14/21＝1/21。", "2 km对应全程的1/21，全程＝2÷1/21＝42（km）。"], "hints": ["前两段的分率，都是以什么为单位“1”？", "最后一段＝全程－前两段。"], "pitfall": "题目没说全程匀速，不要用10分钟占总时间的比例来代替路程比例。", "sourcePage": 4, "diagram": "<svg viewBox=\"0 0 760 225\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:22px;font-family:sans-serif\" aria-label=\"三段骑行路线示意图\"><text x=\"50\" y=\"28\">全程看作1（三段仅作示意，不按比例）</text><line x1=\"70\" y1=\"100\" x2=\"690\" y2=\"100\" stroke=\"#365d50\" stroke-width=\"4\"/><path d=\"M70 90v20 M270 90v20 M510 90v20 M690 90v20\" stroke=\"#365d50\" stroke-width=\"3\"/><text x=\"50\" y=\"140\">起点</text><text x=\"220\" y=\"140\">补给站</text><text x=\"470\" y=\"140\">冲刺点</text><text x=\"650\" y=\"140\">终点</text><text x=\"95\" y=\"78\">全程的2/7</text><text x=\"325\" y=\"78\">全程的2/3</text><text x=\"550\" y=\"78\">？</text><text x=\"510\" y=\"185\">最后一段：2 km</text></svg>"}, {"id": "m-p5", "title": "解决问题5｜两张纸覆盖的面积", "type": "应用", "prompt": "如图，两张纸部分重叠放在桌面上，重叠部分（阴影部分）的面积是9/4 cm²，占长方形纸的3/20，占三角形纸的3/14。这两张纸盖住的桌面面积是多少平方厘米？", "answer": "93/4 cm²（即23又1/4 cm²）", "steps": ["阴影是长方形的3/20，长方形面积＝9/4÷3/20＝15（cm²）。", "阴影是三角形的3/14，三角形面积＝9/4÷3/14＝21/2（cm²）。", "两个面积直接相加会把阴影算两次，要减去1次阴影。", "覆盖面积＝15＋21/2－9/4＝93/4（cm²）。"], "hints": ["同一块阴影，分别对应哪个图形的几分之几？", "两张纸的面积相加时，哪里算了两次？"], "pitfall": "求覆盖面积，要用“两个面积相加－重叠面积”。", "sourcePage": 4, "diagram": "<svg viewBox=\"0 0 760 270\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:24px;font-family:sans-serif\" aria-label=\"题目示意图\"><rect x=\"210\" y=\"30\" width=\"240\" height=\"130\" fill=\"none\" stroke=\"#365d50\" stroke-width=\"3\"/><polygon points=\"130,210 480,110 500,240\" fill=\"none\" stroke=\"#365d50\" stroke-width=\"3\"/><polygon points=\"305,160 450,118 450,160\" fill=\"#c8dbd1\"/><text x=\"510\" y=\"170\">阴影：9/4 cm²</text></svg>"}, {"id": "m-t1", "title": "挑战1｜把除法错算成乘法", "type": "挑战", "prompt": "天天在计算一个数除以5/6时，错算成了乘5/6，算出的结果是25/12。这道除法算式的正确结果是多少？", "answer": "3", "steps": ["先还原原来的数：某数×5/6＝25/12，所以某数＝25/12÷5/6＝5/2。", "原题要算这个数除以5/6。", "正确结果＝5/2÷5/6＝5/2×6/5＝3。"], "hints": ["错误算式里，25/12是谁乘5/6的结果？", "先找出原来的数，再按原题重算。"], "pitfall": "25/12是错误结果，不是原来的被除数。", "sourcePage": 4}, {"id": "m-t2", "title": "挑战2｜增加白兔后的总数变化", "type": "挑战", "prompt": "龙龙的爷爷去年养了白兔和黑兔一共600只，其中白兔只数占总只数的9/25。今年又养了一些白兔，这时白兔只数占总只数的2/5。现在白兔有多少只？", "answer": "256只", "steps": ["去年白兔＝600×9/25＝216（只），黑兔＝600－216＝384（只）。", "今年只增加白兔，所以黑兔仍是384只。", "现在黑兔占总只数的1－2/5＝3/5，现总数＝384÷3/5＝640（只）。", "现在白兔＝640－384＝256（只）。"], "hints": ["增加白兔后，哪个数量不变？", "现在黑兔占现总数的几分之几？"], "pitfall": "增加白兔后总只数也变了，不能直接算600×2/5。", "sourcePage": 4, "diagram": "<svg viewBox=\"0 0 760 250\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:760px;width:100%;height:auto;font-size:23px;font-family:sans-serif\" aria-label=\"数量关系线段图\"><text x=\"50\" y=\"35\">去年：白兔占9/25，总数600只</text><rect x=\"50\" y=\"65\" width=\"180\" height=\"45\" fill=\"#ead5b6\" stroke=\"#365d50\"/><rect x=\"230\" y=\"65\" width=\"320\" height=\"45\" fill=\"#c8dbd1\" stroke=\"#365d50\"/><text x=\"90\" y=\"96\">白兔</text><text x=\"330\" y=\"96\">黑兔</text><text x=\"50\" y=\"150\">今年：白兔增加；黑兔只数不变</text><rect x=\"50\" y=\"175\" width=\"213.33\" height=\"45\" fill=\"#ead5b6\" stroke=\"#365d50\"/><rect x=\"263.33\" y=\"175\" width=\"320\" height=\"45\" fill=\"#c8dbd1\" stroke=\"#365d50\"/><text x=\"70\" y=\"207\">白兔：占2/5</text><text x=\"390\" y=\"207\">黑兔</text></svg>"}]}, "english": {"label": "英语", "name": "Unit 4 A卷 · 能力评价", "pages": "17—18", "description": "词义、语法、阅读与写作，按学生实际试卷讲解。听力题需配套原录音核对。", "questions": [{"id": "e-1-1", "title": "一·1 听句子选图片", "type": "听力", "prompt": "听原试卷录音，选择相符的图片。<img class=\"question-image\" src=\"assets/english/listen-1.png\" alt=\"听力第1题的A、B、C图片\">", "answer": "待原音频核对", "steps": ["先分别说出三幅图中的人、动作和物体。", "听录音时辨认push / pull及具体物体；听到关键词后再核对整句。", "目前未提供本卷原录音，不能据图片或学生所选字母确定答案。"], "hints": ["先说说每幅图有什么不同。", "不要只听到一个熟悉的单词就选。"], "pitfall": "图片只提供选项，无法代替原句。", "sourcePage": 17, "needsAudio": true}, {"id": "e-1-2", "title": "一·2 听句子选图片", "type": "听力", "prompt": "听原试卷录音，选择相符的图片。<img class=\"question-image\" src=\"assets/english/listen-2.png\" alt=\"听力第2题的A、B、C图片\">", "answer": "待原音频核对", "steps": ["先分别说出三幅图中的人、动作和物体。", "听录音时辨认push / pull及具体物体；听到关键词后再核对整句。", "目前未提供本卷原录音，不能据图片或学生所选字母确定答案。"], "hints": ["先说说每幅图有什么不同。", "不要只听到一个熟悉的单词就选。"], "pitfall": "图片只提供选项，无法代替原句。", "sourcePage": 17, "needsAudio": true}, {"id": "e-1-3", "title": "一·3 听句子选图片", "type": "听力", "prompt": "听原试卷录音，选择相符的图片。<img class=\"question-image\" src=\"assets/english/listen-3.png\" alt=\"听力第3题的A、B、C图片\">", "answer": "待原音频核对", "steps": ["先分别说出三幅图中的人、动作和物体。", "听录音时辨认push / pull及具体物体；听到关键词后再核对整句。", "目前未提供本卷原录音，不能据图片或学生所选字母确定答案。"], "hints": ["先说说每幅图有什么不同。", "不要只听到一个熟悉的单词就选。"], "pitfall": "图片只提供选项，无法代替原句。", "sourcePage": 17, "needsAudio": true}, {"id": "e-1-4", "title": "一·4 听句子选图片", "type": "听力", "prompt": "听原试卷录音，选择相符的图片。<img class=\"question-image\" src=\"assets/english/listen-4.png\" alt=\"听力第4题的A、B、C图片\">", "answer": "待原音频核对", "steps": ["先分别说出三幅图中的人、动作和物体。", "听录音时辨认push / pull及具体物体；听到关键词后再核对整句。", "目前未提供本卷原录音，不能据图片或学生所选字母确定答案。"], "hints": ["先说说每幅图有什么不同。", "不要只听到一个熟悉的单词就选。"], "pitfall": "图片只提供选项，无法代替原句。", "sourcePage": 17, "needsAudio": true}, {"id": "e-1-5", "title": "一·5 听句子选图片", "type": "听力", "prompt": "听原试卷录音，选择相符的图片。<img class=\"question-image\" src=\"assets/english/listen-5.png\" alt=\"听力第5题的A、B、C图片\">", "answer": "待原音频核对", "steps": ["先分别说出三幅图中的人、动作和物体。", "听录音时辨认push / pull及具体物体；听到关键词后再核对整句。", "目前未提供本卷原录音，不能据图片或学生所选字母确定答案。"], "hints": ["先说说每幅图有什么不同。", "不要只听到一个熟悉的单词就选。"], "pitfall": "图片只提供选项，无法代替原句。", "sourcePage": 17, "needsAudio": true}, {"id": "e-2", "title": "二 图片排序", "type": "听力", "prompt": "听原试卷录音，用数字1—5给下列图片排序。<img class=\"question-image\" src=\"assets/english/listen-sort.png\" alt=\"五幅待排序图片\">", "answer": "待原音频核对", "steps": ["先给图起名字：拉行李箱、拉箱子、拉门、掰手腕、推箱子。", "每听到一句，先找到对应图片，再写出它在录音中的序号。", "无原录音，不把照片上的1、2、3、5、4当成已确认答案。"], "hints": ["每幅图写的是录音序号，不是图片序号。"], "pitfall": "推和拉的方向不同；排序不能靠图片排列猜。", "sourcePage": 17, "needsAudio": true}, {"id": "e-3-1", "title": "三·1 听问句选答语", "type": "听力", "prompt": "听原录音中的问句，再选择答语。<ol class=\"options\" type=\"A\"><li>A force.</li><li>A book.</li><li>A desk.</li></ol>", "answer": "待原音频核对", "steps": ["先读懂三个答语，再听问句问的是物体、一般疑问，还是比较关系。", "选项内容符合常识也不代表回答了录音里的问题。", "没有原问句，不能确认字母答案。"], "hints": ["注意问句开头是what、who，还是do / is / are。"], "pitfall": "先确定问什么，再找对应答语。", "sourcePage": 17, "needsAudio": true}, {"id": "e-3-2", "title": "三·2 听问句选答语", "type": "听力", "prompt": "听原录音中的问句，再选择答语。<ol class=\"options\" type=\"A\"><li>Yes, they are.</li><li>No, it isn’t.</li><li>Yes, I do.</li></ol>", "answer": "待原音频核对", "steps": ["先读懂三个答语，再听问句问的是物体、一般疑问，还是比较关系。", "选项内容符合常识也不代表回答了录音里的问题。", "没有原问句，不能确认字母答案。"], "hints": ["注意问句开头是what、who，还是do / is / are。"], "pitfall": "先确定问什么，再找对应答语。", "sourcePage": 17, "needsAudio": true}, {"id": "e-3-3", "title": "三·3 听问句选答语", "type": "听力", "prompt": "听原录音中的问句，再选择答语。<ol class=\"options\" type=\"A\"><li>It can make things move far.</li><li>It can make things move slowly.</li><li>It can’t make things away from us.</li></ol>", "answer": "待原音频核对", "steps": ["先读懂三个答语，再听问句问的是物体、一般疑问，还是比较关系。", "选项内容符合常识也不代表回答了录音里的问题。", "没有原问句，不能确认字母答案。"], "hints": ["注意问句开头是what、who，还是do / is / are。"], "pitfall": "先确定问什么，再找对应答语。", "sourcePage": 17, "needsAudio": true}, {"id": "e-3-4", "title": "三·4 听问句选答语", "type": "听力", "prompt": "听原录音中的问句，再选择答语。<ol class=\"options\" type=\"A\"><li>A tortoise is slower than a rabbit.</li><li>A horse is heavier than a rabbit.</li><li>A dog is faster than a rabbit.</li></ol>", "answer": "待原音频核对", "steps": ["先读懂三个答语，再听问句问的是物体、一般疑问，还是比较关系。", "选项内容符合常识也不代表回答了录音里的问题。", "没有原问句，不能确认字母答案。"], "hints": ["注意问句开头是what、who，还是do / is / are。"], "pitfall": "先确定问什么，再找对应答语。", "sourcePage": 17, "needsAudio": true}, {"id": "e-3-5", "title": "三·5 听问句选答语", "type": "听力", "prompt": "听原录音中的问句，再选择答语。<ol class=\"options\" type=\"A\"><li>My father is the tallest in my family.</li><li>My little sister is the youngest in my family.</li><li>My grandma is the oldest in my family.</li></ol>", "answer": "待原音频核对", "steps": ["先读懂三个答语，再听问句问的是物体、一般疑问，还是比较关系。", "选项内容符合常识也不代表回答了录音里的问题。", "没有原问句，不能确认字母答案。"], "hints": ["注意问句开头是what、who，还是do / is / are。"], "pitfall": "先确定问什么，再找对应答语。", "sourcePage": 17, "needsAudio": true}, {"id": "e-4-1", "title": "四·1 听经历判断正误", "type": "听力", "prompt": "听Diandian收拾卧室的经历，判断T或F。<p>Diandian cleaned his bedroom on Saturday.</p>", "answer": "待原音频核对", "steps": ["先找出句子中要核对的信息：时间、轻重、力度、速度。", "听原录音后，对照句子中的每个关键信息。", "原录音未提供，照片里的T/F暂不能作为标准答案。"], "hints": ["特别留意at first、heavy / light、big / small、only等词。"], "pitfall": "一句中只要有一个关键信息不符，整句就应判F。", "sourcePage": 17, "needsAudio": true}, {"id": "e-4-2", "title": "四·2 听经历判断正误", "type": "听力", "prompt": "听Diandian收拾卧室的经历，判断T或F。<p>The desk was light at first.</p>", "answer": "待原音频核对", "steps": ["先找出句子中要核对的信息：时间、轻重、力度、速度。", "听原录音后，对照句子中的每个关键信息。", "原录音未提供，照片里的T/F暂不能作为标准答案。"], "hints": ["特别留意at first、heavy / light、big / small、only等词。"], "pitfall": "一句中只要有一个关键信息不符，整句就应判F。", "sourcePage": 17, "needsAudio": true}, {"id": "e-4-3", "title": "四·3 听经历判断正误", "type": "听力", "prompt": "听Diandian收拾卧室的经历，判断T或F。<p>Diandian used a big force to push the light desk.</p>", "answer": "待原音频核对", "steps": ["先找出句子中要核对的信息：时间、轻重、力度、速度。", "听原录音后，对照句子中的每个关键信息。", "原录音未提供，照片里的T/F暂不能作为标准答案。"], "hints": ["特别留意at first、heavy / light、big / small、only等词。"], "pitfall": "一句中只要有一个关键信息不符，整句就应判F。", "sourcePage": 17, "needsAudio": true}, {"id": "e-4-4", "title": "四·4 听经历判断正误", "type": "听力", "prompt": "听Diandian收拾卧室的经历，判断T或F。<p>The heavy desk moved very slowly.</p>", "answer": "待原音频核对", "steps": ["先找出句子中要核对的信息：时间、轻重、力度、速度。", "听原录音后，对照句子中的每个关键信息。", "原录音未提供，照片里的T/F暂不能作为标准答案。"], "hints": ["特别留意at first、heavy / light、big / small、only等词。"], "pitfall": "一句中只要有一个关键信息不符，整句就应判F。", "sourcePage": 17, "needsAudio": true}, {"id": "e-4-5", "title": "四·5 听经历判断正误", "type": "听力", "prompt": "听Diandian收拾卧室的经历，判断T或F。<p>Diandian only used a small push to move the desk.</p>", "answer": "待原音频核对", "steps": ["先找出句子中要核对的信息：时间、轻重、力度、速度。", "听原录音后，对照句子中的每个关键信息。", "原录音未提供，照片里的T/F暂不能作为标准答案。"], "hints": ["特别留意at first、heavy / light、big / small、only等词。"], "pitfall": "一句中只要有一个关键信息不符，整句就应判F。", "sourcePage": 17, "needsAudio": true}, {"id": "e-5-1", "title": "五·1 根据英文释义选词", "type": "词义理解", "prompt": "<p>词库：A. force　B. easy　C. movement　D. tortoise　E. difficult</p><p>It is hard to do something.</p>", "answer": "E. difficult", "steps": ["hard在这里表示“困难的”，不是“坚硬的”。", "difficult与这里的hard意思相近，所以选E。"], "hints": ["先抓定义中的关键词，再用完整意思核对。"], "pitfall": "这件事情做起来很难。", "sourcePage": 17}, {"id": "e-5-2", "title": "五·2 根据英文释义选词", "type": "词义理解", "prompt": "<p>词库：A. force　B. easy　C. movement　D. tortoise　E. difficult</p><p>It is not hard, and you can do it well.</p>", "answer": "B. easy", "steps": ["not hard表示“不困难”。", "能比较容易做好，对应easy，所以选B。"], "hints": ["先抓定义中的关键词，再用完整意思核对。"], "pitfall": "先读出not，意思会反过来。", "sourcePage": 17}, {"id": "e-5-3", "title": "五·3 根据英文释义选词", "type": "词义理解", "prompt": "<p>词库：A. force　B. easy　C. movement　D. tortoise　E. difficult</p><p>It is an animal, and it moves slowly.</p>", "answer": "D. tortoise", "steps": ["先找类别animal：答案必须是动物。", "再看moves slowly：移动很慢；对应tortoise乌龟。"], "hints": ["先抓定义中的关键词，再用完整意思核对。"], "pitfall": "slowly是线索，不是要填的名词。", "sourcePage": 17}, {"id": "e-5-4", "title": "五·4 根据英文释义选词", "type": "词义理解", "prompt": "<p>词库：A. force　B. easy　C. movement　D. tortoise　E. difficult</p><p>It is the act of moving from one place to another.</p>", "answer": "C. movement", "steps": ["moving from one place to another表示从一个地方移动到另一个地方。", "这里给出“移动这一行为”的定义，对应名词movement。"], "hints": ["先抓定义中的关键词，再用完整意思核对。"], "pitfall": "movement是运动、移动，不是产生运动的力。", "sourcePage": 17}, {"id": "e-5-5", "title": "五·5 根据英文释义选词", "type": "词义理解", "prompt": "<p>词库：A. force　B. easy　C. movement　D. tortoise　E. difficult</p><p>It is a push or a pull, and it makes things move or stop moving.</p>", "answer": "A. force", "steps": ["push和pull都是力的形式。", "能让物体开始运动或停止运动，对应force。"], "hints": ["先抓定义中的关键词，再用完整意思核对。"], "pitfall": "不要把force（力）和movement（移动）混淆。", "sourcePage": 17}, {"id": "e-6-1", "title": "六·1 看图写单词", "type": "词汇填空", "prompt": "<img class=\"question-image\" src=\"assets/english/word-pictures.png\" alt=\"对应五小题的图片\"><p>The box is easy to move. It is ______.</p>", "answer": "light", "steps": ["先看easy to move：容易移动。", "图中的箱子轻，所以用light，不是再填easy。"], "hints": ["light的意思是什么？"], "pitfall": "不能忽略图片，也不能把前半句直接重复到空里。", "sourcePage": 17}, {"id": "e-6-2", "title": "六·2 看图写单词", "type": "词汇填空", "prompt": "<img class=\"question-image\" src=\"assets/english/word-pictures.png\" alt=\"对应五小题的图片\"><p>The bag is hard to move. It is very ______.</p>", "answer": "heavy", "steps": ["hard to move表示难以移动。", "图中男孩拎着很重的包，对应heavy。"], "hints": ["与light相反的词是什么？"], "pitfall": "heavy注意拼写，不是heavey。", "sourcePage": 17}, {"id": "e-6-3", "title": "六·3 看图写单词", "type": "词汇填空", "prompt": "<img class=\"question-image\" src=\"assets/english/word-pictures.png\" alt=\"对应五小题的图片\"><p>Please ______ the door, Lingling.</p>", "answer": "pull", "steps": ["先看图，门朝人物这边打开，对应pull。", "Please开头的祈使句，后面用动词原形。"], "hints": ["门是朝自己靠近，还是远离自己？"], "pitfall": "动词要看动作方向，不能看到door就随便填push。", "sourcePage": 17}, {"id": "e-6-4", "title": "六·4 看图写单词", "type": "词汇填空", "prompt": "<img class=\"question-image\" src=\"assets/english/word-pictures.png\" alt=\"对应五小题的图片\"><p>Look! Some boys are helping the man ______ the car.</p>", "answer": "push", "steps": ["男孩们从车后面用力推车，对应push。", "help somebody do something：帮助某人做某事。这里可以用push。", "help后也可以用to push；本题要求根据图片写单词，填push即可。"], "hints": ["谁在对车做什么？"], "pitfall": "difficult形容难度，不能充当这里需要的动作。", "sourcePage": 17}, {"id": "e-6-5", "title": "六·5 看图写单词", "type": "词汇填空", "prompt": "<img class=\"question-image\" src=\"assets/english/word-pictures.png\" alt=\"对应五小题的图片\"><p>The girl was happy. She ______ the game.</p>", "answer": "won", "steps": ["领奖台上女孩获胜，所以用win。", "was表明这里叙述过去发生的事，要把win变为won。"], "hints": ["前一句里的was提醒你用什么时态？"], "pitfall": "不能填help或helped；要先根据情境选对动作，再考虑时态。", "sourcePage": 17}, {"id": "e-7-1", "title": "七·1 括号选词", "type": "语法运用", "prompt": "<p>This bag is heavy, but that box is ______ (heavier / heavy) than this bag.</p>", "answer": "heavier", "steps": ["先找比较标志than。", "比较这只箱子和这个包，heavy变比较级heavier：辅音字母加y结尾，变y为i再加er。"], "hints": ["这里在比较几个东西？"], "pitfall": "heavy是原级；有than时需要比较级。", "sourcePage": 17}, {"id": "e-7-2", "title": "七·2 括号选词", "type": "语法运用", "prompt": "<p>My sister is ______ (younger / the youngest) in my family.</p>", "answer": "the youngest", "steps": ["in my family给出了家庭这个比较范围。", "句意是“妹妹是我家最小的”，应选最高级the youngest。"], "hints": ["是在说“更小”，还是“全家最小”？"], "pitfall": "younger常需要说明和谁比；这里考查范围内的“最”。", "sourcePage": 17}, {"id": "e-7-3", "title": "七·3 括号选词", "type": "语法运用", "prompt": "<p>When you pull things, it moves ______ (away from / towards) you.</p>", "answer": "towards", "steps": ["pull表示拉，一般使物体朝用力者靠近。", "towards you表示朝你靠近；away from you表示远离你。", "理解整句时，it指被拉动的物体。"], "hints": ["试着做一下拉抽屉的动作。"], "pitfall": "不能把push和pull的运动方向记反。", "sourcePage": 17}, {"id": "e-7-4", "title": "七·4 括号选词", "type": "语法运用", "prompt": "<p>The old man walks ______ (slowly / lonely) in the park after dinner every day.</p>", "answer": "slowly", "steps": ["要描述老人“怎样走”，这里需要说明动作方式。", "slowly表示慢慢地，修饰walks；lonely表示孤独的。"], "hints": ["问自己：这句话是在说走路速度，还是人的感受？"], "pitfall": "拼写slowly，不是slowly的漏字或变形。", "sourcePage": 17}, {"id": "e-7-5", "title": "七·5 括号选词", "type": "语法运用", "prompt": "<p>It is easy ______ (move / to move) a light box.</p>", "answer": "to move", "steps": ["句型是It is + 形容词 + to do something。", "easy后接to move，整句表示“移动一个轻箱子很容易”。"], "hints": ["把句型读完整：It is easy…"], "pitfall": "to不能丢；这里不是It moves a box。", "sourcePage": 17}, {"id": "e-8-1", "title": "八·1 句子配图片", "type": "读句配图", "prompt": "<img class=\"question-image\" src=\"assets/english/match-pictures.png\" alt=\"A放风筝，B秋千，C推车，D跑步Lily，E窗户\"><p>We can push or pull the window to open or close it.</p>", "answer": "E", "steps": ["先找window，确认物体是窗户。", "E图画的是开关窗户，push / pull表示推或拉，因此选E。"], "hints": ["window对应哪幅图？"], "pitfall": "D图是跑步，不能仅凭人物数量选。", "sourcePage": 17}, {"id": "e-8-2", "title": "八·2 句子配图片", "type": "读句配图", "prompt": "<img class=\"question-image\" src=\"assets/english/match-pictures.png\" alt=\"A放风筝，B秋千，C推车，D跑步Lily，E窗户\"><p>The girl pushes the swing. It moves away from her.</p>", "answer": "B", "steps": ["swing是秋千；pushes是推。", "B图对应推秋千；后一句away from her说明秋千远离女孩。"], "hints": ["swing指哪样东西？"], "pitfall": "C图是小推车，不是秋千。", "sourcePage": 17}, {"id": "e-8-3", "title": "八·3 句子配图片", "type": "读句配图", "prompt": "<img class=\"question-image\" src=\"assets/english/match-pictures.png\" alt=\"A放风筝，B秋千，C推车，D跑步Lily，E窗户\"><p>The wind gives a big force and pushes the kite up high in the sky.</p>", "answer": "A", "steps": ["先找kite：风筝。", "A图画的是放风筝，与up high in the sky对应。"], "hints": ["哪幅图里有风筝？"], "pitfall": "big force说的是风的作用，不是看到大物体就选。", "sourcePage": 17}, {"id": "e-8-4", "title": "八·4 句子配图片", "type": "读句配图", "prompt": "<img class=\"question-image\" src=\"assets/english/match-pictures.png\" alt=\"A放风筝，B秋千，C推车，D跑步Lily，E窗户\"><p>The little girl uses a small force to push a little cart in the park.</p>", "answer": "C", "steps": ["cart是小推车。", "C图女孩推小车，动作是push，选C。"], "hints": ["先确认cart这个名词。"], "pitfall": "B图是秋千，不能把两幅带器材的图混淆。", "sourcePage": 17}, {"id": "e-8-5", "title": "八·5 句子配图片", "type": "读句配图", "prompt": "<img class=\"question-image\" src=\"assets/english/match-pictures.png\" alt=\"A放风筝，B秋千，C推车，D跑步Lily，E窗户\"><p>All the children run fast, and Lily is the fastest.</p>", "answer": "D", "steps": ["run fast说明场景是跑步。", "D图标出了Lily；the fastest表示几个孩子中跑得最快。"], "hints": ["fast和the fastest分别是什么意思？"], "pitfall": "E是窗户图，不是跑步图。", "sourcePage": 17}, {"id": "e-9-1", "title": "九·1 补全对话", "type": "对话理解", "prompt": "<details class=\"context\" open><summary>展开原文：完整对话</summary><p>Tiantian: 1. ______</p><p>Lanlan: OK. I think we can do an experiment.</p><p>Tiantian: 2. ______</p><p>Lanlan: Yes! Look! The big push makes the toy car move fast.</p><p>Tiantian: That’s right. 3. ______</p><p>Lanlan: Yes. The small push makes it move slowly.</p><p>Tiantian: 4. ______</p><p>Lanlan: Wow, I can see that clearly.</p><p>Tiantian: Me too. 5. ______</p><p>Lanlan: Great! The experiment helps a lot.</p></details><p>选择第1空：</p><ol class=\"options\" type=\"A\"><li>Then things move slowly when we use a small force.</li><li>Do you think a bigger force makes things move faster?</li><li>I know how a force changes the speed now.</li><li>Let’s talk about forces and speed.</li><li>Look! The ball moves the fastest when we push hard.</li></ol>", "answer": "D", "steps": ["开头要先提出谈论的话题。", "Let’s talk about forces and speed提出“谈谈力和速度”，后面OK及做实验自然承接。"], "hints": ["看后一句OK回应什么类型的句子。"], "pitfall": "必须结合前后问答关系，不能只看一个单词。", "sourcePage": 18}, {"id": "e-9-2", "title": "九·2 补全对话", "type": "对话理解", "prompt": "<details class=\"context\" open><summary>展开原文：完整对话</summary><p>Tiantian: 1. ______</p><p>Lanlan: OK. I think we can do an experiment.</p><p>Tiantian: 2. ______</p><p>Lanlan: Yes! Look! The big push makes the toy car move fast.</p><p>Tiantian: That’s right. 3. ______</p><p>Lanlan: Yes. The small push makes it move slowly.</p><p>Tiantian: 4. ______</p><p>Lanlan: Wow, I can see that clearly.</p><p>Tiantian: Me too. 5. ______</p><p>Lanlan: Great! The experiment helps a lot.</p></details><p>选择第2空：</p><ol class=\"options\" type=\"A\"><li>Then things move slowly when we use a small force.</li><li>Do you think a bigger force makes things move faster?</li><li>I know how a force changes the speed now.</li><li>Let’s talk about forces and speed.</li><li>Look! The ball moves the fastest when we push hard.</li></ol>", "answer": "B", "steps": ["空后Lanlan用Yes回答，需要前面提出问题。", "B问“更大的力会让物体动得更快吗”，下句用大推力的小车实验回答。"], "hints": ["寻找能让下一句Yes成立的问句。"], "pitfall": "必须结合前后问答关系，不能只看一个单词。", "sourcePage": 18}, {"id": "e-9-3", "title": "九·3 补全对话", "type": "对话理解", "prompt": "<details class=\"context\" open><summary>展开原文：完整对话</summary><p>Tiantian: 1. ______</p><p>Lanlan: OK. I think we can do an experiment.</p><p>Tiantian: 2. ______</p><p>Lanlan: Yes! Look! The big push makes the toy car move fast.</p><p>Tiantian: That’s right. 3. ______</p><p>Lanlan: Yes. The small push makes it move slowly.</p><p>Tiantian: 4. ______</p><p>Lanlan: Wow, I can see that clearly.</p><p>Tiantian: Me too. 5. ______</p><p>Lanlan: Great! The experiment helps a lot.</p></details><p>选择第3空：</p><ol class=\"options\" type=\"A\"><li>Then things move slowly when we use a small force.</li><li>Do you think a bigger force makes things move faster?</li><li>I know how a force changes the speed now.</li><li>Let’s talk about forces and speed.</li><li>Look! The ball moves the fastest when we push hard.</li></ol>", "answer": "A", "steps": ["前面刚说大推力让玩具车移动得快。", "Then引出小力的对比：用小力时，物体移动得慢；后句重复印证这一点。"], "hints": ["大推力之后，接着讨论哪种力度？"], "pitfall": "必须结合前后问答关系，不能只看一个单词。", "sourcePage": 18}, {"id": "e-9-4", "title": "九·4 补全对话", "type": "对话理解", "prompt": "<details class=\"context\" open><summary>展开原文：完整对话</summary><p>Tiantian: 1. ______</p><p>Lanlan: OK. I think we can do an experiment.</p><p>Tiantian: 2. ______</p><p>Lanlan: Yes! Look! The big push makes the toy car move fast.</p><p>Tiantian: That’s right. 3. ______</p><p>Lanlan: Yes. The small push makes it move slowly.</p><p>Tiantian: 4. ______</p><p>Lanlan: Wow, I can see that clearly.</p><p>Tiantian: Me too. 5. ______</p><p>Lanlan: Great! The experiment helps a lot.</p></details><p>选择第4空：</p><ol class=\"options\" type=\"A\"><li>Then things move slowly when we use a small force.</li><li>Do you think a bigger force makes things move faster?</li><li>I know how a force changes the speed now.</li><li>Let’s talk about forces and speed.</li><li>Look! The ball moves the fastest when we push hard.</li></ol>", "answer": "E", "steps": ["后一句Wow, I can see that clearly表示看到了明显现象。", "E用Look展示“用力推时，球移动得最快”的现象，最符合观察语境。"], "hints": ["后面说“我清楚地看到了”，前面应是什么内容？"], "pitfall": "必须结合前后问答关系，不能只看一个单词。", "sourcePage": 18}, {"id": "e-9-5", "title": "九·5 补全对话", "type": "对话理解", "prompt": "<details class=\"context\" open><summary>展开原文：完整对话</summary><p>Tiantian: 1. ______</p><p>Lanlan: OK. I think we can do an experiment.</p><p>Tiantian: 2. ______</p><p>Lanlan: Yes! Look! The big push makes the toy car move fast.</p><p>Tiantian: That’s right. 3. ______</p><p>Lanlan: Yes. The small push makes it move slowly.</p><p>Tiantian: 4. ______</p><p>Lanlan: Wow, I can see that clearly.</p><p>Tiantian: Me too. 5. ______</p><p>Lanlan: Great! The experiment helps a lot.</p></details><p>选择第5空：</p><ol class=\"options\" type=\"A\"><li>Then things move slowly when we use a small force.</li><li>Do you think a bigger force makes things move faster?</li><li>I know how a force changes the speed now.</li><li>Let’s talk about forces and speed.</li><li>Look! The ball moves the fastest when we push hard.</li></ol>", "answer": "C", "steps": ["对话接近结尾，需要总结实验所得。", "C说“现在我知道力怎样改变速度了”，与后面的实验很有帮助对应。"], "hints": ["结尾要总结学会了什么。"], "pitfall": "必须结合前后问答关系，不能只看一个单词。", "sourcePage": 18}, {"id": "e-10-1", "title": "十·1 音乐短文填空", "type": "完形填空", "prompt": "<details class=\"context\" open><summary>展开原文：音乐与力</summary><p>My friend Lily and I like music, but how do we use forces when we play music?</p><p>When I play the piano, I use my fingers to 1. ______ the white and black keys. When I use a 2. ______ force to push, the sound is loud and strong. When I use a small force to push the keys, the sound is 3. ______ and gentle.</p><p>Lily plays the violin next to me. She holds the bow and 4. ______ it across the strings. When she moves the bow 5. ______, the music is slow. It makes everyone feel relaxed. We both learn that forces can change how our music sounds.</p></details><p>选择第1空：</p><ol class=\"options\" type=\"A\"><li>pull</li><li>push</li><li>open</li></ol>", "answer": "B. push", "steps": ["钢琴演奏时，手指按下琴键，是push这个动作。", "后文两次出现push，能回到原文验证。"], "hints": ["手指怎样让琴键动起来？"], "pitfall": "use fingers to后要接动词原形。", "sourcePage": 18}, {"id": "e-10-2", "title": "十·2 音乐短文填空", "type": "完形填空", "prompt": "<details class=\"context\" open><summary>展开原文：音乐与力</summary><p>My friend Lily and I like music, but how do we use forces when we play music?</p><p>When I play the piano, I use my fingers to 1. ______ the white and black keys. When I use a 2. ______ force to push, the sound is loud and strong. When I use a small force to push the keys, the sound is 3. ______ and gentle.</p><p>Lily plays the violin next to me. She holds the bow and 4. ______ it across the strings. When she moves the bow 5. ______, the music is slow. It makes everyone feel relaxed. We both learn that forces can change how our music sounds.</p></details><p>选择第2空：</p><ol class=\"options\" type=\"A\"><li>big</li><li>bigger</li><li>biggest</li></ol>", "answer": "A. big", "steps": ["这里说“用大力时，声音响亮有力”。", "句中没有在比较两种力，也没有最高级范围，用原级big。"], "hints": ["这里只描述力的大小，还是在比较？"], "pitfall": "不要见到力度就机械选比较级bigger。", "sourcePage": 18}, {"id": "e-10-3", "title": "十·3 音乐短文填空", "type": "完形填空", "prompt": "<details class=\"context\" open><summary>展开原文：音乐与力</summary><p>My friend Lily and I like music, but how do we use forces when we play music?</p><p>When I play the piano, I use my fingers to 1. ______ the white and black keys. When I use a 2. ______ force to push, the sound is loud and strong. When I use a small force to push the keys, the sound is 3. ______ and gentle.</p><p>Lily plays the violin next to me. She holds the bow and 4. ______ it across the strings. When she moves the bow 5. ______, the music is slow. It makes everyone feel relaxed. We both learn that forces can change how our music sounds.</p></details><p>选择第3空：</p><ol class=\"options\" type=\"A\"><li>loud</li><li>low</li><li>strong</li></ol>", "answer": "B. low", "steps": ["前面大力对应loud and strong；这里小力对应较轻柔的声音。", "三个选项中low与gentle搭配，最符合本题上下文。"], "hints": ["先与前面的loud and strong作对照。"], "pitfall": "这里的low是试卷给出的声音描述，不要选与小力语境相反的loud或strong。", "sourcePage": 18}, {"id": "e-10-4", "title": "十·4 音乐短文填空", "type": "完形填空", "prompt": "<details class=\"context\" open><summary>展开原文：音乐与力</summary><p>My friend Lily and I like music, but how do we use forces when we play music?</p><p>When I play the piano, I use my fingers to 1. ______ the white and black keys. When I use a 2. ______ force to push, the sound is loud and strong. When I use a small force to push the keys, the sound is 3. ______ and gentle.</p><p>Lily plays the violin next to me. She holds the bow and 4. ______ it across the strings. When she moves the bow 5. ______, the music is slow. It makes everyone feel relaxed. We both learn that forces can change how our music sounds.</p></details><p>选择第4空：</p><ol class=\"options\" type=\"A\"><li>pushes</li><li>pulls</li><li>throws</li></ol>", "answer": "B. pulls", "steps": ["拉小提琴时，弓沿琴弦拉动，选pulls。", "主语She为第三人称单数，动词形式pulls已经在选项中给出。"], "hints": ["bow是琴弓，across the strings是沿着琴弦。"], "pitfall": "throws是扔，不能用于这里演奏琴弓的动作。", "sourcePage": 18}, {"id": "e-10-5", "title": "十·5 音乐短文填空", "type": "完形填空", "prompt": "<details class=\"context\" open><summary>展开原文：音乐与力</summary><p>My friend Lily and I like music, but how do we use forces when we play music?</p><p>When I play the piano, I use my fingers to 1. ______ the white and black keys. When I use a 2. ______ force to push, the sound is loud and strong. When I use a small force to push the keys, the sound is 3. ______ and gentle.</p><p>Lily plays the violin next to me. She holds the bow and 4. ______ it across the strings. When she moves the bow 5. ______, the music is slow. It makes everyone feel relaxed. We both learn that forces can change how our music sounds.</p></details><p>选择第5空：</p><ol class=\"options\" type=\"A\"><li>slow</li><li>quickly</li><li>slowly</li></ol>", "answer": "C. slowly", "steps": ["空格说明“怎样移动琴弓”，需要副词。", "后面the music is slow说明节奏慢，所以选slowly，不选quickly。"], "hints": ["先判断修饰的是动作moves，还是名词。"], "pitfall": "slow是形容词；这里需要slowly修饰moves。", "sourcePage": 18}, {"id": "e-11-1", "title": "十一·1 原文转表格", "type": "信息提取", "prompt": "<details class=\"context\" open><summary>展开原文：生活中的推和拉</summary><p>We use pushes and pulls every day. Many things need forces to work.</p><p>We often ride bicycles. When we ride, we push the pedals. A big force makes the bicycle move fast. A small force makes it move slowly.</p><p>We can see drawers at home. We pull a drawer to open it. We push it to close it. The pull and push both work on a drawer.</p><p>An air pump is helpful in our life. We move its handle with repeated pushes and pulls. The force fills balls or tyres with air.</p><p>The push and pull work together for the air pump. The faster we move the handle, the more air it pumps into balls or tyres.</p><p>From these things, we learn a rule: Different forces can change how fast things move.</p></details><p>We use a 1. ______ force to push bicycle pedals. → The bicycle moves slowly.</p>", "answer": "small", "steps": ["根据自行车段落，A small force makes it move slowly。", "结果是慢慢移动，原因应是小力，填small。"], "hints": ["根据moves slowly回原文找对应的力度。"], "pitfall": "force是空格后已有的名词，不能再填force。", "sourcePage": 18}, {"id": "e-11-2", "title": "十一·2 原文转表格", "type": "信息提取", "prompt": "<details class=\"context\" open><summary>展开原文：生活中的推和拉</summary><p>We use pushes and pulls every day. Many things need forces to work.</p><p>We often ride bicycles. When we ride, we push the pedals. A big force makes the bicycle move fast. A small force makes it move slowly.</p><p>We can see drawers at home. We pull a drawer to open it. We push it to close it. The pull and push both work on a drawer.</p><p>An air pump is helpful in our life. We move its handle with repeated pushes and pulls. The force fills balls or tyres with air.</p><p>The push and pull work together for the air pump. The faster we move the handle, the more air it pumps into balls or tyres.</p><p>From these things, we learn a rule: Different forces can change how fast things move.</p></details><p>We 2. ______ the drawer. → The drawer opens.</p>", "answer": "pull", "steps": ["原文说We pull a drawer to open it。", "结果是opens，应该是拉抽屉，填pull。"], "hints": ["打开抽屉应该推还是拉？"], "pitfall": "不能填move或open来代替本题要求的具体用力动作。", "sourcePage": 18}, {"id": "e-11-3", "title": "十一·3 原文转表格", "type": "信息提取", "prompt": "<details class=\"context\" open><summary>展开原文：生活中的推和拉</summary><p>We use pushes and pulls every day. Many things need forces to work.</p><p>We often ride bicycles. When we ride, we push the pedals. A big force makes the bicycle move fast. A small force makes it move slowly.</p><p>We can see drawers at home. We pull a drawer to open it. We push it to close it. The pull and push both work on a drawer.</p><p>An air pump is helpful in our life. We move its handle with repeated pushes and pulls. The force fills balls or tyres with air.</p><p>The push and pull work together for the air pump. The faster we move the handle, the more air it pumps into balls or tyres.</p><p>From these things, we learn a rule: Different forces can change how fast things move.</p></details><p>We push the drawer. → The drawer 3. ______.</p>", "answer": "closes", "steps": ["原文说We push it to close it。", "表格主语是The drawer单数，结果句写The drawer closes。"], "hints": ["原文close在句子里需要什么形式？"], "pitfall": "不能照抄close原形；这里drawer作主语，动词加s。", "sourcePage": 18}, {"id": "e-11-4", "title": "十一·4 原文转表格", "type": "信息提取", "prompt": "<details class=\"context\" open><summary>展开原文：生活中的推和拉</summary><p>We use pushes and pulls every day. Many things need forces to work.</p><p>We often ride bicycles. When we ride, we push the pedals. A big force makes the bicycle move fast. A small force makes it move slowly.</p><p>We can see drawers at home. We pull a drawer to open it. We push it to close it. The pull and push both work on a drawer.</p><p>An air pump is helpful in our life. We move its handle with repeated pushes and pulls. The force fills balls or tyres with air.</p><p>The push and pull work together for the air pump. The faster we move the handle, the more air it pumps into balls or tyres.</p><p>From these things, we learn a rule: Different forces can change how fast things move.</p></details><p>We move the air pump handle 4. ______. → The air pump fills balls or tyres with more air.</p>", "answer": "faster（填fast或quickly在这个表格句中也能表达原因）", "steps": ["原文The faster we move the handle, the more air it pumps…表示手柄动得越快，泵入空气越多。", "表中结果有more air，优先保留原文的比较关系，填faster。", "若只描述“快速移动手柄”这一原因，fast或quickly也能组成通顺且符合文意的表格句；不要把合理表达机械判错。"], "hints": ["more air对应手柄怎样移动？"], "pitfall": "speed是名词，不能直接放在move the handle后表示“快速地”。", "sourcePage": 18}, {"id": "e-11-5", "title": "十一·5 原文转表格", "type": "信息提取", "prompt": "<details class=\"context\" open><summary>展开原文：生活中的推和拉</summary><p>We use pushes and pulls every day. Many things need forces to work.</p><p>We often ride bicycles. When we ride, we push the pedals. A big force makes the bicycle move fast. A small force makes it move slowly.</p><p>We can see drawers at home. We pull a drawer to open it. We push it to close it. The pull and push both work on a drawer.</p><p>An air pump is helpful in our life. We move its handle with repeated pushes and pulls. The force fills balls or tyres with air.</p><p>The push and pull work together for the air pump. The faster we move the handle, the more air it pumps into balls or tyres.</p><p>From these things, we learn a rule: Different forces can change how fast things move.</p></details><p>We move the air pump handle fast. → The air pump fills balls or tyres with more 5. ______.</p>", "answer": "air", "steps": ["原文两次说明打气筒给球或轮胎充air。", "with more air表示充入更多空气，填air。"], "hints": ["打气筒往球里充的是什么？"], "pitfall": "air是空气，不能写成in或其他介词。", "sourcePage": 18}, {"id": "e-12-1", "title": "十二·1 拔苗助长阅读", "type": "阅读理解", "prompt": "<details class=\"context\" open><summary>展开原文：拔苗助长完整故事</summary><p>There is a farmer. He grows rice seedlings in his field. But the seedlings grow slowly. He feels worried. “Why can’t they grow faster?” he thinks.</p><p>One day, the farmer has an idea. “If I pull them up, they will grow faster!” he says. He thinks a strong pull can make the seedlings grow tall quickly.</p><p>He works in the field all day. He pulls every seedling up with his hands. He uses a lot of forces. When he finishes, he feels very tired but happy.</p><p>When he gets home, he tells his family, “I helped the seedlings grow today! They are taller now.” His son does not understand.</p><p>The next morning, the farmer’s son runs to the field. He is shocked. All the seedlings are dead! They are yellow and weak.</p></details><p>Why is the farmer worried?</p><ol class=\"options\" type=\"A\"><li>Because the field is too small.</li><li>Because the seedlings grow very slowly.</li><li>Because he has no food to eat.</li></ol>", "answer": "B", "steps": ["定位开头：But the seedlings grow slowly. He feels worried。", "担心的原因是秧苗长得慢，不是田太小或没有食物。"], "hints": ["从worried前一句找原因。"], "pitfall": "不凭“农民很穷”等生活印象添加原文没有的信息。", "sourcePage": 18}, {"id": "e-12-2", "title": "十二·2 拔苗助长阅读", "type": "阅读理解", "prompt": "<details class=\"context\" open><summary>展开原文：拔苗助长完整故事</summary><p>There is a farmer. He grows rice seedlings in his field. But the seedlings grow slowly. He feels worried. “Why can’t they grow faster?” he thinks.</p><p>One day, the farmer has an idea. “If I pull them up, they will grow faster!” he says. He thinks a strong pull can make the seedlings grow tall quickly.</p><p>He works in the field all day. He pulls every seedling up with his hands. He uses a lot of forces. When he finishes, he feels very tired but happy.</p><p>When he gets home, he tells his family, “I helped the seedlings grow today! They are taller now.” His son does not understand.</p><p>The next morning, the farmer’s son runs to the field. He is shocked. All the seedlings are dead! They are yellow and weak.</p></details><p>What does the farmer do to make the seedlings grow faster?</p><ol class=\"options\" type=\"A\"><li>He pulls them up with his hands.</li><li>He waters them every day.</li><li>He plants new seeds.</li></ol>", "answer": "A", "steps": ["定位He pulls every seedling up with his hands。", "题目问他实际做了什么，答案是用手把秧苗往上拔。"], "hints": ["题目问does，不是在问怎样种田才正确。"], "pitfall": "浇水是合理做法，但不是这位农民在故事中做的事。", "sourcePage": 18}, {"id": "e-12-3", "title": "十二·3 拔苗助长阅读", "type": "阅读理解", "prompt": "<details class=\"context\" open><summary>展开原文：拔苗助长完整故事</summary><p>There is a farmer. He grows rice seedlings in his field. But the seedlings grow slowly. He feels worried. “Why can’t they grow faster?” he thinks.</p><p>One day, the farmer has an idea. “If I pull them up, they will grow faster!” he says. He thinks a strong pull can make the seedlings grow tall quickly.</p><p>He works in the field all day. He pulls every seedling up with his hands. He uses a lot of forces. When he finishes, he feels very tired but happy.</p><p>When he gets home, he tells his family, “I helped the seedlings grow today! They are taller now.” His son does not understand.</p><p>The next morning, the farmer’s son runs to the field. He is shocked. All the seedlings are dead! They are yellow and weak.</p></details><p>What happens to the seedlings the next morning?</p><ol class=\"options\" type=\"A\"><li>They grow very tall.</li><li>They all die.</li><li>They turn green again.</li></ol>", "answer": "B", "steps": ["定位故事最后：All the seedlings are dead。", "dead对应die，说明秧苗全死了。"], "hints": ["特别看the next morning这一时间。"], "pitfall": "不能把父亲前一天说的They are taller now当作最终结果。", "sourcePage": 18}, {"id": "e-12-4", "title": "十二·4 拔苗助长阅读", "type": "阅读理解", "prompt": "<details class=\"context\" open><summary>展开原文：拔苗助长完整故事</summary><p>There is a farmer. He grows rice seedlings in his field. But the seedlings grow slowly. He feels worried. “Why can’t they grow faster?” he thinks.</p><p>One day, the farmer has an idea. “If I pull them up, they will grow faster!” he says. He thinks a strong pull can make the seedlings grow tall quickly.</p><p>He works in the field all day. He pulls every seedling up with his hands. He uses a lot of forces. When he finishes, he feels very tired but happy.</p><p>When he gets home, he tells his family, “I helped the seedlings grow today! They are taller now.” His son does not understand.</p><p>The next morning, the farmer’s son runs to the field. He is shocked. All the seedlings are dead! They are yellow and weak.</p></details><p>The underlined word “shocked” means “______” in Chinese.</p><ol class=\"options\" type=\"A\"><li>惊喜的</li><li>震惊的</li><li>害怕的</li></ol>", "answer": "B", "steps": ["先读shocked后面的情况：秧苗全部死了，又黄又弱。", "儿子看到意外且糟糕的结果，感到震惊，选B。"], "hints": ["这个结果是好消息，还是坏消息？"], "pitfall": "“害怕”和“震惊”不是一回事；要结合意外结果判断。", "sourcePage": 18}, {"id": "e-12-5", "title": "十二·5 拔苗助长阅读", "type": "阅读理解", "prompt": "<details class=\"context\" open><summary>展开原文：拔苗助长完整故事</summary><p>There is a farmer. He grows rice seedlings in his field. But the seedlings grow slowly. He feels worried. “Why can’t they grow faster?” he thinks.</p><p>One day, the farmer has an idea. “If I pull them up, they will grow faster!” he says. He thinks a strong pull can make the seedlings grow tall quickly.</p><p>He works in the field all day. He pulls every seedling up with his hands. He uses a lot of forces. When he finishes, he feels very tired but happy.</p><p>When he gets home, he tells his family, “I helped the seedlings grow today! They are taller now.” His son does not understand.</p><p>The next morning, the farmer’s son runs to the field. He is shocked. All the seedlings are dead! They are yellow and weak.</p></details><p>What can we learn from this story?</p><ol class=\"options\" type=\"A\"><li>We can use a strong force to make things grow faster.</li><li>Pulling is always a bad way to help plants.</li><li>We should not use the wrong way to speed things up.</li></ol>", "answer": "C", "steps": ["故事中的农民急着让秧苗长快，却用了错误的方法，导致秧苗死亡。", "C概括了“不能用错误的方法急于求成”。", "A恰好是农民的错误想法；B中的always过于绝对。"], "hints": ["把故事的做法、后果连起来想。"], "pitfall": "寓意应概括故事，不要只抓pull就选带pulling的句子。", "sourcePage": 18}, {"id": "e-13", "title": "十三 作文：我身边的推和拉", "type": "写作", "prompt": "<h3>The Push and Pull Around Me</h3><p>根据表格提示，介绍生活中用到推力或拉力的情况，贴合生活实际，不少于6句话。</p><table><tr><th>Place</th><th>Cause</th><th>Effect</th></tr><tr><td>At school</td><td>pull the chair</td><td>The chair moves towards me.</td></tr><tr><td>At home</td><td>…</td><td>…</td></tr><tr><td>For fun</td><td>…</td><td>…</td></tr></table><p>试卷提供的开头：I can see pushes and pulls everywhere in my life. At school, when I use a small force to pull the ______, it moves ______ me.</p><p><strong>先口头说清楚，再写：谁？做什么？怎样用力？有什么结果？</strong></p>", "answer": "开放题：内容合理、句子完整即可；下面提供一份7句示例，供核对思路。", "steps": ["第一步：三个情景各选一个动作。学校拉椅子；家里拉抽屉；玩耍时推玩具车。", "第二步：每个情景先说四点。例：I → pull the chair → a small force → towards me。", "第三步：动作和力度有两种表达，选一种即可：I use a small force to pull the chair. / I pull the chair with a small force.", "第四步：另写结果句：It moves towards me. 家里可以写The drawer opens. 玩具车可以写It moves away from me.", "第五步：开头1句＋三个情景各2句＝7句，满足不少于6句。读一遍检查句首大写、句末标点及动作和结果是否一致。", "参考示例：I can see pushes and pulls everywhere in my life. At school, I use a small force to pull the chair. It moves towards me. At home, I pull the drawer with a small force. The drawer opens. For fun, I use a big force to push my toy car. It moves away from me."], "hints": ["先不要急着写英文，把学校、家里、玩耍三个情景的四点用中文说清楚。", "家里补句：At home, I use ______ to ______. The drawer ______.", "玩耍时只给词：push / toy car / a big force / away from me，让他独立组织。"], "pitfall": "use后面先写用了什么力，再用to接动作；with前面要有完整动作。I use drawer…缺少正确结构；to wards应写towards。", "sourcePage": 18}]}};
